import { writeFileSync } from 'node:fs'; import { join } from 'node:path'; import { encodeBackup } from '../../../src/engine/hypertree/persistence/backup.js'; import { createInternalPolicyContext } from '../../../src/engine/hypertree/edition/index.js'; import { countNodes } from '../../harness/large-map/fixtures.mjs';
const HERE=join(process.cwd(),'tests/fixtures/large-map'); const paid=createInternalPolicyContext({edition:'paid'}); let seq=0;
const file=(name)=>({id:'f-'+seq++,kind:'file',name,data:{},children:[]}); const folder=(id,name,children=[])=>({id,kind:'folder',name,data:{},children});
function wide(){const root=folder('root','Wide flat');for(let i=0;i<20;i++){const c=folder('cat-'+(i+1),'Category '+(i+1));root.children.push(c)}let n=379;for(let i=0;i<n;i++)root.children[i%20].children.push(file('wide-'+String(i).padStart(3,'0')+'.txt'));return root}
function dense(){const root=folder('root','Dense single folder');const cats=[];for(let i=0;i<20;i++){const c=folder('cat-'+(i+1),'Category '+(i+1));root.children.push(c);cats.push(c)}for(let i=0;i<280;i++)cats[0].children.push(file('dense-'+String(i).padStart(3,'0')+'.txt'));for(let i=0;i<98;i++)cats[1+(i%19)].children.push(file('spread-'+String(i).padStart(3,'0')+'.txt'));root.children.push(file('README-root.md'));return root}
function deep(){const root=folder('root','Deep chain');let parent=root;for(let i=1;i<=6;i++){const c=folder('depth-'+i,'Depth '+i);parent.children.push(c);parent=c}let n=393;for(let i=0;i<n;i++){let p=root;const steps=(i%6)+1;for(let d=1;d<=steps;d++)p=p.children.find(x=>x.kind==='folder');p.children.push(file('deep-'+String(i).padStart(3,'0')+'.txt'))}return root}
for(const [name,tree] of [['wide',wide()],['dense',dense()],['deep',deep()]]){if(countNodes(tree)!==400)throw Error(name+' count '+countNodes(tree));const enc=await encodeBackup({tree,registry:new Map(),mapName:'FileOrbit-'+name+'-400',policyContext:paid,cryptoApi:globalThis.crypto});const bytes=new Uint8Array(await enc.blob.arrayBuffer());writeFileSync(join(HERE,'FileOrbit-'+name+'-400.orbit'),bytes);console.log(name,countNodes(tree),bytes.length)}

